"INSERT OR IGNORE INTO events (slug, city, title, organization_id, venue_name, venue_address, start_at, end_at, start_utc, end_utc, timezone, format, description_short, description_long, registration_url, cost_type, cost_min, cost_max, cost_notes, cpe_eligible, cpe_hours, cpe_body, cpe_notes, topics, audience_level, status, source, source_url, reviewer_notes, hold, auto_publish_at) VALUES ('ciso-fireside-at-sundance-2026-11-05', 'saltlake', 'CISO Fireside at Sundance', (SELECT id FROM organizations WHERE slug='sl-ciso'), 'Sundance', 'Sundance, UT 84604', '2026-11-05T09:00:00', '2026-11-05T17:00:00', '2026-11-05T16:00:00.000Z', '2026-11-06T00:00:00.000Z', 'America/Denver', 'in_person', 'A one-day single-track gathering for CISOs, deputy CISOs and VP-level security leaders from Utah and beyond', 'A one-day single-track gathering for CISOs, deputy CISOs and VP-level security leaders from Utah and beyond. Sessions cover strategy, incident response, board communication, AI, governance and the human side of security leadership, with no sales pitches on stage.', 'https://luma.com/8mxbzmo9', 'unknown', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[\"leadership\", \"grc\", \"ai\", \"social\"]', 'senior', 'pending_review', 'research', 'https://luma.com/8mxbzmo9', 'Research 2026-10-22 from https://luma.com/8mxbzmo9. Times are placeholders; the page gives no time. Held: research confidence was medium. Research note: Luma page shows no date or time; Nov 5 2026 is from dev.events listing. Registration is Request to Join with host approval, so effectively invite-only for senior security leaders.', 1, NULL);",
"INSERT OR IGNORE INTO events (slug, city, title, organization_id, venue_name, venue_address, start_at, end_at, start_utc, end_utc, timezone, format, description_short, description_long, registration_url, cost_type, cost_min, cost_max, cost_notes, cpe_eligible, cpe_hours, cpe_body, cpe_notes, topics, audience_level, status, source, source_url, reviewer_notes, hold, auto_publish_at) VALUES ('open-source-securitycon-north-america-2026-11-09', 'saltlake', 'Open Source SecurityCon North America', (SELECT id FROM organizations WHERE slug='openssf'), 'Salt Lake City (venue not stated on source page)', 'Salt Lake City, UT', '2026-11-09T09:00:00', '2026-11-09T17:00:00', '2026-11-09T16:00:00.000Z', '2026-11-10T00:00:00.000Z', 'America/Denver', 'in_person', 'A one-day event co-hosted by CNCF and OpenSSF on open source and cloud native security, covering supply chain security, secure development, identity and access, and open source policy', 'A one-day event co-hosted by CNCF and OpenSSF on open source and cloud native security, covering supply chain security, secure development, identity and access, and open source policy. Aimed at developers, security engineers, public sector experts and CISOs.', 'https://events.linuxfoundation.org/kubecon-cloudnativecon-north-america/co-located-events/open-source-securitycon/', 'unknown', NULL, NULL, 'Included with All-Access In-Person KubeCon + CloudNativeCon pass; standalone price not stated', NULL, NULL, NULL, NULL, '[\"appsec\", \"cloud\"]', 'open', 'pending_review', 'research', 'https://events.linuxfoundation.org/kubecon-cloudnativecon-north-america/co-located-events/open-source-securitycon/', 'Research 2026-10-22 from https://events.linuxfoundation.org/kubecon-cloudnativecon-north-america/co-located-events/open-source-securitycon/. Times are placeholders; the page gives no time. Held: the venue is not announced yet. Research note: Co-located with KubeCon NA, Nov 9-12 2026 in Salt Lake City.', 1, NULL);",
